+  std::string file=c.s("boundary_map_csv");angular=!file.empty();if(file.empty())file=c.s("boundary_csv");if(file.empty())return;
+  Csv csv(file);int it=csv.col("day"),iv=csv.col("speed_kms"),id=csv.col("density_1au_cm3",false);if(id<0)id=csv.col("density_cm3");int ib=csv.col("br_1au_nt",false);if(ib<0)ib=csv.col("b_r_nt",false);int itemp=csv.col("temperature_K",false),ilo=angular?csv.col("lon_rad"):-1,ila=angular?csv.col("lat_rad"):-1;
