+A conserved(const A&p,double g){A u=p;u[1]*=p[0];u[2]*=p[0];u[3]*=p[0];u[4]=p[4]/(g-1)+.5*p[0]*(p[1]*p[1]+p[2]*p[2]+p[3]*p[3])+.5*(p[5]*p[5]+p[6]*p[6]+p[7]*p[7]+p[8]*p[8]);return u;}
