+double limiter(double a,double b){if(a*b<=0)return 0;return std::copysign(std::min({2*std::abs(a),2*std::abs(b),.5*std::abs(a+b)}),a);}
+void npy(const fs::path&file,const std::vector<float>&x,const std::vector<int>&shape){std::ofstream f(file,std::ios::binary);std::string h="{'descr': '<f4', 'fortran_order': False, 'shape': (";for(int n:shape)h+=std::to_string(n)+", ";h+="), }";while((10+h.size()+1)%64)h+=' ';h+='\n';f.write("\x93NUMPY\x01\x00",8);uint16_t n=h.size();f.put(n&255);f.put(n>>8);f.write(h.data(),h.size());f.write((const char*)x.data(),x.size()*sizeof(float));if(!f)throw std::runtime_error("Cannot write "+file.string());}
