+ double ch=1,mindt=1e99,rejected=0,maxdiv=0;long steps=0;int snapshotidx=0;bool unit_test=false;
+ size_t idx(int i,int j,int k)const{return ((size_t)(i+2)*sy+j+2)*sz+k+2;}
+ Solver(const Config&cfg):c(cfg),boundary(c){nr=c.i("nr",64);nt=c.i("ntheta",8);np=c.i("nphi",48);if(nr<3||nt<2||np<4)throw std::runtime_error("Need nr>=3,ntheta>=2,nphi>=4");gamma=c.d("gamma",1.5);if(gamma<=1)throw std::runtime_error("gamma must exceed 1");rmin=c.d("rmin_au",.1);rmax=c.d("rmax_au",2.4);latmax=c.d("latmax_deg",60)*PI/180;dp=2*PI/np;dt=2*latmax/nt;gm=c.d("gravity_gm",.0002959122082855911);cfl=c.d("cfl",.35);order=c.i("order",2);sy=nt+4;sz=np+4;total=(size_t)(nr+4)*sy*sz;if(total>3000000)throw std::runtime_error("Grid too large for conservative memory budget");
+  rf.resize(nr+1);rc.resize(nr);tf.resize(nt+1);tc.resize(nt);pc.resize(np);volume.resize(total);for(int i=0;i<=nr;++i)rf[i]=c.s("radial_grid","uniform")=="log"?rmin*std::pow(rmax/rmin,double(i)/nr):rmin+(rmax-rmin)*i/nr;for(int i=0;i<nr;++i)rc[i]=c.s("radial_grid","uniform")=="log"?std::sqrt(rf[i]*rf[i+1]):.5*(rf[i]+rf[i+1]);for(int j=0;j<=nt;++j)tf[j]=PI/2-latmax+j*dt;for(int j=0;j<nt;++j)tc[j]=.5*(tf[j]+tf[j+1]);for(int k=0;k<np;++k)pc[k]=(k+.5)*dp;
