+  out=c.s("output_dir","output");fs::create_directories(out);std::string probe_file=c.s("probes_csv");if(!probe_file.empty()){Csv csv(probe_file);int t=csv.col("day"),r=csv.col("r_au"),lo=csv.col("lon_rad"),la=csv.col("lat_rad"),id=csv.col("probe_id",false);for(auto &z:csv.rows)probes.push_back({z[t],z[r],z[lo],z[la],id<0?0:(int)z[id]});std::sort(probes.begin(),probes.end(),[](auto&a,auto&b){return a.t<b.t;});probeout.open(out/"probe.csv");probeout<<"day,probe_id,r_au,lon_rad,lat_rad,n_cm3,speed_kms,flux_cm2_s,vr_kms,vtheta_kms,vphi_kms,p_npa,Br_nt,Btheta_nt,Bphi_nt\n"<<std::setprecision(12);}
