+ A initial(double time,double radius,double th,double ph,bool retard=true)const{double lag=retard?(radius-rmin)/(boundary.speed*1000/VUNIT):0;auto b=boundary.sample(time-lag,ph,PI/2-th);double v=b[0]*1000/VUNIT;V e=er(th,ph),az=ep(ph);A z={};z[0]=b[1]/(radius*radius);V vel=mul(e,v);double vp=c.d("boundary_vphi_kms",0)*1000/VUNIT*rmin/radius;vel=add(vel,mul(az,vp));double br=b[2]*1e-9/BUNIT/(radius*radius);V mag=add(mul(e,br),mul(az,-boundary.rotation*(radius-c.d("source_surface_au",0.01))*std::sin(th)*br/v));double temperature=b[3]*std::pow(radius/rmin,-2*(gamma-1));z[4]=c.d("thermal_pressure_factor",2)*z[0]*1e6*KB*temperature/PUNIT;for(int d=0;d<3;++d){z[1+d]=vel[d];z[5+d]=mag[d];}return z;}
+ bool fill(const std::vector<A>&state,double time){int bad=0;
+  #pragma omp parallel for collapse(3) reduction(+:bad) schedule(static)
