+ bool compute_rhs(const std::vector<A>&state,double time){if(!fill(state,time))return false;
+  const size_t strides[3]={(size_t)sy*sz,(size_t)sz,1};
+  for(int d=0;d<3;++d){int ni=nr+(d==0),nj=nt+(d==1),nk=np+(d==2);
+   #pragma omp parallel for collapse(3) schedule(static)
+   for(int i=0;i<ni;++i)for(int j=0;j<nj;++j)for(int k=0;k<nk;++k){size_t b=idx(i,j,k),a=b-strides[d];A l=p[a],r=p[b];if(order==2){for(int v=0;v<NV;++v){l[v]+=.5*limiter(p[a][v]-p[a-strides[d]][v],p[b][v]-p[a][v]);r[v]-=.5*limiter(p[b][v]-p[a][v],p[b+strides[d]][v]-p[b][v]);}}Face f=faces[d][b];ff[d][b]=riemann(l,r,f.n,f.area,gamma,ch);}
