+  for(int i=0;i<nr;++i)for(int j=0;j<nt;++j)for(int k=0;k<np;++k){size_t a=idx(i,j,k);const A&z=p[a];double vel=std::sqrt(z[1]*z[1]+z[2]*z[2]+z[3]*z[3]),b2=z[5]*z[5]+z[6]*z[6]+z[7]*z[7];mx=std::max(mx,vel+std::sqrt(gamma*z[4]/z[0]+b2/z[0]));double area=faces[0][a].area+faces[0][idx(i+1,j,k)].area+faces[1][a].area+faces[1][idx(i,j+1,k)].area+faces[2][a].area+faces[2][idx(i,j,k+1)].area;geom=std::max(geom,.5*area/volume[a]);}ch=c.d("cleaning_speed_factor",1)*mx;return cfl/(std::max(mx,ch)*geom);
